from checked_integer import *
from json_lines_io import *
from json_document_batch import *
from ail import write_stdout_bytes
import sys

def json_lines_transform_file(path: str, size: int, mode: str, spec: str) -> JsonDocuments:
    if size <= 0:
        raise ValueError
    if mode == 'select':
        json_pointer_segments(spec)
        selected = json_lines_read_file(path, size)
        return json_documents_select(selected, spec)
    elif mode == 'project':
        projection: JsonProjection = json_projection_parse(spec)
        projected = json_lines_read_file(path, size)
        return json_documents_project(projected, projection)
    else:
        raise ValueError

def main() -> int:
    if len(sys.argv) != 5:
        print('usage: json_lines_transform INPUT SIZE MODE SPEC', file=sys.stderr)
        return 2
    try:
        size: int = parse_int64_decimal(sys.argv[2])
        result = json_lines_transform_file(sys.argv[1], size, sys.argv[3], sys.argv[4])
        rendered: str = json_documents_render_lines(result)
        write_stdout_bytes(rendered.encode('utf-8'))
        return 0
    except ValueError:
        print('invalid JSON Lines, UTF-8, size, mode, or specification', file=sys.stderr)
        return 2
    except KeyError:
        print('JSON pointer target is missing', file=sys.stderr)
        return 2
    except OSError:
        print('JSON Lines input or output failed', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
